import base64,os,subprocess,ast
code=base64.b64decode("").decode("utf-8")
ast.parse(code)
open("/content/fly/webui_character.py","w",encoding="utf-8").write(code)
print("wrote", len(code))
ps=subprocess.run("ps -eo pid,cmd | grep [w]ebui_character.py",shell=True,capture_output=True,text=True).stdout.strip()
if not ps:
    subprocess.Popen("nohup python -u /content/fly/webui_character.py > /content/fly/webui.log 2>&1 &",shell=True,executable="/bin/bash")
    print("LAUNCHED")
else: print("running", ps)
